.ser-product-page{padding:28px 0 64px;color:var(--ser-ink)}
.ser-product-breadcrumb{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px;color:var(--ser-muted);font-size:13px;line-height:1.6}
.ser-product-page .hero{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;margin-bottom:32px}
.ser-product-page .panel{border-radius:18px;border-color:var(--ser-line);background:var(--ser-surface);box-shadow:0 8px 28px #102a4308;min-width:0}
.ser-product-page .gallery{padding:16px}
.ser-product-page .gallery img.main{border-radius:12px;aspect-ratio:4/3}
.ser-product-page .thumbs{grid-template-columns:repeat(auto-fill,minmax(64px,80px));gap:10px}
.ser-product-page .thumbs button,.ser-product-page .thumbs img{border-radius:8px}
.ser-product-page .copy{padding:32px}
.ser-product-page .service-tag{background:var(--ser-mist);color:var(--ser-primary);border-radius:6px;font-size:11px;letter-spacing:.08em;margin-bottom:14px}
.ser-product-page .copy h1{font-size:clamp(28px,3vw,40px);font-weight:800;line-height:1.2;letter-spacing:-.03em;overflow-wrap:anywhere;color:var(--ser-navy);margin-bottom:10px}
.ser-product-sku{font-size:12px;color:var(--ser-muted);margin-bottom:18px}
.ser-product-page .copy>p{font-size:15px;line-height:1.8;overflow-wrap:anywhere}
.ser-product-page .price{padding-top:22px;border-top:1px solid var(--ser-line);margin:24px 0 6px;gap:10px}
.ser-price-label{width:100%;font-size:12px;color:var(--ser-muted)}
.ser-product-page .price strong{font-size:34px;font-weight:800;color:var(--ser-navy);line-height:1.3}
.ser-product-page .copy .ser-price-note{font-size:12px;line-height:1.6}
.ser-product-page .mini-metrics{grid-template-columns:1fr;gap:0;margin:20px 0}
.ser-product-page .mini-card{display:grid;grid-template-columns:140px minmax(0,1fr);gap:16px;border:0;border-radius:0;padding:10px 0;background:none}
.ser-product-page .mini-card strong{font-size:13px;font-weight:700;line-height:1.7}
.ser-product-page .mini-card span{margin:0;font-size:13px;line-height:1.7;overflow-wrap:anywhere}
.ser-product-page .actions{gap:12px;margin-top:22px}
.ser-product-page .actions .btn{border-radius:10px;min-height:48px;font-size:14px;padding:12px 20px}
.ser-product-page .actions .primary{background:var(--ser-navy);box-shadow:none}
.ser-product-page .details{grid-template-columns:minmax(0,1fr) 340px;gap:28px;padding-bottom:32px}
.ser-product-page .section{padding:32px}
.ser-product-page .section>h2{font-size:24px;font-weight:750;line-height:1.4;color:var(--ser-navy);margin-bottom:20px}
.ser-product-page .highlights+.ser-description-title{margin-top:28px}
.ser-product-richtext{font-size:15px;line-height:1.9;color:#334e68;overflow-wrap:anywhere}
.ser-product-richtext h2,.ser-product-richtext h3,.ser-product-richtext h4{font-weight:700;line-height:1.5;margin:24px 0 12px;color:var(--ser-navy)}
.ser-product-richtext h2{font-size:21px}.ser-product-richtext h3{font-size:18px}.ser-product-richtext>:first-child{margin-top:0}
.ser-product-richtext p{margin-bottom:16px}.ser-product-richtext ul,.ser-product-richtext ol{padding-left:24px;margin:16px 0}.ser-product-richtext ul{list-style:disc}.ser-product-richtext ol{list-style:decimal}
.ser-product-richtext a{color:var(--ser-primary);text-decoration:underline}.ser-product-richtext img,.ser-product-richtext video{max-width:100%;height:auto}.ser-product-richtext table{display:block;max-width:100%;overflow-x:auto}.ser-product-richtext td,.ser-product-richtext th{padding:10px;border:1px solid var(--ser-line)}
.ser-product-page .booking-card{position:static;gap:16px}
.ser-product-page .booking-card .panel{padding:24px}
.ser-product-page .booking-card h4{font-size:18px;font-weight:750;line-height:1.5;margin-bottom:12px}
.ser-product-page .booking-card p{font-size:14px;line-height:1.8}
.ser-product-page .booking-dossier{background:var(--ser-mist);border-top:3px solid var(--ser-accent)}
.ser-product-page .booking-dossier-item strong,.ser-product-page .step strong{font-size:13px;font-weight:700}.ser-product-page .step-index{border-radius:8px;flex-shrink:0}
.ser-product-page a:focus-visible,.ser-product-page button:focus-visible{outline:3px solid var(--ser-accent);outline-offset:3px}
@media(max-width:980px){.ser-product-page .hero,.ser-product-page .details{grid-template-columns:minmax(0,1fr)}.ser-product-page .booking-card{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.ser-product-page .copy,.ser-product-page .section{padding:24px 20px}.ser-product-page .booking-card{grid-template-columns:minmax(0,1fr)}.ser-product-page .mini-card{grid-template-columns:1fr;gap:2px}.ser-product-page .actions{flex-direction:column}.ser-product-page .actions .btn{width:100%}.ser-product-page .price strong{font-size:30px}.ser-product-page .hero{gap:20px}.ser-product-breadcrumb{font-size:12px}}
